def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = ""

    for word in words:
        # Handle words longer than width by cutting them into pieces
        while len(word) > width:
            piece = word[:width]
            word = word[width:]

            # Place the piece as a word
            if not current_line:
                current_line = piece
            elif len(current_line) + 1 + len(piece) <= width:
                current_line += " " + piece
            else:
                lines.append(current_line)
                current_line = piece

        # Now word is <= width (or empty if it was exactly divisible)
        if not word:
            continue

        if not current_line:
            current_line = word
        elif len(current_line) + 1 + len(word) <= width:
            current_line += " " + word
        else:
            lines.append(current_line)
            current_line = word

    if current_line:
        lines.append(current_line)

    return lines


# Test script
def test_wrap():
    tests = [
        # Given examples
        (("the quick brown fox", 10), ["the quick", "brown fox"]),
        (("abcdefghij", 4), ["abcd", "efgh", "ij"]),
        (("", 5), []),
        (("a b", 0), ValueError),

        # Additional tests
        (("hello", 5), ["hello"]),
        (("hello world", 5), ["hello", "world"]),
        (("hello world", 11), ["hello world"]),
        (("a b c", 1), ["a", "b", "c"]),
        (("longword", 3), ["lon", "gwo", "rd"]),
        (("a longword b", 3), ["a", "lon", "gwo", "rd", "b"]),
        (("  spaced  out  ", 10), ["spaced", "out"]),
        (("word", 10), ["word"]),
        (("word", 4), ["word"]),
        (("word", 3), ["wor", "d"]),
        (("a bc def", 2), ["a", "bc", "de", "f"]),
    ]

    passed = 0
    failed = 0

    for i, (args, expected) in enumerate(tests):
        try:
            result = wrap(*args)
            if result == expected:
                print(f"Test {i+1}: PASSED")
                passed += 1
            else:
                print(f"Test {i+1}: FAILED - wrap{args} = {result}, expected {expected}")
                failed += 1
        except Exception as e:
            if expected is ValueError and isinstance(e, ValueError):
                print(f"Test {i+1}: PASSED (ValueError raised)")
                passed += 1
            else:
                print(f"Test {i+1}: FAILED - wrap{args} raised {type(e).__name__}: {e}")
                failed += 1

    print(f"\nPassed: {passed}, Failed: {failed}")
    if failed == 0:
        print("ALL TESTS PASSED")
    else:
        print("NOT ALL TESTS PASSED")

test_wrap()

